#!/usr/bin/env python3
"""Street Legends backend: Rock Candy enemy-drop item (backend / Publish).

USER SPEC (exact): item name "Rock Candy"; sells for $300 per oz; when
collected it goes into the player's item screen (inventory). Art is the
uploaded white-crystal bag image, embedded below as a data-URI icon_url
(the GitHub push tool cannot carry binary PNGs, so no raw GitHub URL is
used; if the client cannot render the data URI, the row falls back to
the diamond icon and the item still functions).

READINGS (NOT the user's decisions - correctable):
- "50$ more attack" is read as 50% more attack for 1 minute (Grass was
  50% health, Pills 50% energy; attack is not money, so $ is treated as
  a typo for %). The buff multiplies damage dealt by 1.5 for 60s.
- "1 - 10 fights" is read as a 1-in-10 chance EACH fight, following the
  user's own correction on Pills (where "1 - 6" meant 1-in-6 per fight,
  not a 1-to-6-fight gap). Flat 10% roll on every standard battle
  victory, 1 oz when it lands, any enemy type. NOT an interval counter,
  NO random-gap counter. PvP and guild-raid victories have no loot path in the
  snapshot and are not hooked.
- Use: consumes 1 oz; for 60 seconds attacks deal 50% more damage. A
  second use while active refreshes the 60s timer (no stacking). When
  the buff expires, damage returns to normal.
- Sell: $300 per oz, 1 oz per tap, from the item screen, no prompt.

Design notes (mirroring the Grass/Pills patches; live /app may differ,
hence guards; this patch is STANDALONE - it never assumes Grass or
Pills code ran, but it IS order-tolerant of them: the pool exclusion
extends a pool line already modified by Grass and/or Pills):
- Inventory is player["inventory"], a list of item_id strings or dicts;
  Rock Candy is stored as ONE stacked dict {"item_id": "rock_candy",
  "qty": N, "unit": "oz", ...} rather than one entry per oz.
- Rock Candy is added to ALL_ITEMS so the inventory-details endpoint
  returns it (items absent from ALL_ITEMS are invisible on the item
  screen). It is EXCLUDED from the generic random drop pool so it
  cannot double-drop.
- Buffs live in player["active_buffs"] as {type: "attack", percent,
  ...}. Rock Candy reuses that system with an expires_at timestamp plus
  a large battles_remaining (10000) so the time expiry - not the
  per-battle decrement - is what ends it.
- ATTACK HOOK (why damage sites, not the stat): player_stats["attack"]
  feeds BOTH damage lines in battle_action AND the level-up growth
  (stats.attack * 1.05). Mutating player_stats would permanently
  inflate base attack on a level-up during the buff. So the patch
  computes a live multiplier (_rc_atk_mult, expiry-checked, from the
  buff's percent) and multiplies damage at exactly the two damage
  sites (normal attack and skill). Level-up math stays unboosted.
  Territory-boss and PvP battle damage paths are NOT hooked (same
  scope as the drop: standard monster battles only).
- The generic sell endpoint pays value//2 and pops one whole entry, so
  it must NOT be used for Rock Candy: dedicated use/sell endpoints
  below pay exactly $300/oz and decrement qty. The frontend hides the
  generic Sell/Equip buttons for Rock Candy rows.
- RUN ORDER: Grass -> Pills -> Rock Candy. This patch tolerates pool
  lines already modified by Grass/Pills, but the Grass/Pills patches
  use exact-match pool anchors and do NOT tolerate a rock-candy-
  modified line: if Rock Candy runs first, their pool parts print a
  WARNING and that item could double-drop from the generic pool.
"""
import re, sys
from pathlib import Path

ROOT = Path(sys.argv[1]) if len(sys.argv) > 1 else Path("/app")
SRV = ROOT / "backend/server.py"

ROCK_CANDY_URL = "data:image/jpeg;base64,"

CATALOG = '''
# ROCK_CANDY_ITEM_CATALOG: Rock Candy enemy-drop item (see patch header for spec/readings).
ALL_ITEMS["rock_candy"] = {
    "id": "rock_candy", "name": "Rock Candy", "category": "consumable",
    "description": "Bag of rock candy. Use: +50% attack for 60 seconds. Sells for $300 per oz.",
    "icon": "diamond", "icon_url": ''' + '"' + ROCK_CANDY_URL + '"' + ''',
    "rarity": "common", "equipment_type": "consumable",
    "stats_bonus": {}, "level_requirement": 1, "value": 300,
}
'''

ROUTES = '''
# ROCK_CANDY_ITEM_USE / ROCK_CANDY_ITEM_SELL: dedicated Rock Candy endpoints ($300/oz, 1 oz per sell tap).
@api_router.post("/players/{player_id}/rock-candy/use")
async def use_rock_candy(player_id: str):
    """Use 1 oz of Rock Candy: +50% attack for 60 seconds (refreshes if active)."""
    player = await db.players.find_one({"id": player_id})
    if not player:
        raise HTTPException(status_code=404, detail="Player not found")
    inv = player.get("inventory", [])
    r_idx = None
    r_qty = 0
    for _i, _it in enumerate(inv):
        if isinstance(_it, dict) and _it.get("item_id") == "rock_candy":
            r_idx, r_qty = _i, _it.get("qty", 1)
            break
        if isinstance(_it, str) and _it == "rock_candy":
            r_idx, r_qty = _i, 1
            break
    if r_idx is None or r_qty < 1:
        raise HTTPException(status_code=400, detail="No Rock Candy in inventory")
    if r_qty <= 1:
        inv.pop(r_idx)
    elif isinstance(inv[r_idx], dict):
        inv[r_idx]["qty"] = r_qty - 1
    else:
        inv.pop(r_idx)
    stats = player.get("stats", {})
    base_attack = stats.get("attack", 10)
    gain = int(base_attack * 0.5)
    boosted_attack = int(base_attack * 1.5)
    expiry = (datetime.utcnow() + timedelta(minutes=1)).isoformat()
    buffs = [b for b in player.get("active_buffs", []) if b.get("item_id") != "rock_candy"]
    buffs.append({
        "id": "rock_candy_" + str(uuid.uuid4())[:8], "item_id": "rock_candy", "name": "Rock Candy",
        "type": "attack", "amount": gain, "percent": 0.5,
        "battles_remaining": 10000, "expires_at": expiry, "icon": "diamond",
    })
    await db.players.update_one(
        {"id": player_id},
        {"$set": {"inventory": inv, "active_buffs": buffs}},
    )
    return {"message": "Rock Candy used! +50% attack for 60 seconds.", "base_attack": base_attack,
            "boosted_attack": boosted_attack, "expires_at": expiry, "oz_left": r_qty - 1}


@api_router.post("/players/{player_id}/rock-candy/sell")
async def sell_rock_candy(player_id: str, qty: int = 1):
    """Sell Rock Candy at $300 per oz."""
    if qty < 1:
        raise HTTPException(status_code=400, detail="Quantity must be at least 1")
    player = await db.players.find_one({"id": player_id})
    if not player:
        raise HTTPException(status_code=404, detail="Player not found")
    inv = player.get("inventory", [])
    r_idx = None
    r_qty = 0
    for _i, _it in enumerate(inv):
        if isinstance(_it, dict) and _it.get("item_id") == "rock_candy":
            r_idx, r_qty = _i, _it.get("qty", 1)
            break
        if isinstance(_it, str) and _it == "rock_candy":
            r_idx, r_qty = _i, 1
            break
    if r_idx is None or r_qty < qty:
        raise HTTPException(status_code=400, detail="Not enough Rock Candy in inventory")
    if r_qty <= qty:
        inv.pop(r_idx)
        left = 0
    elif isinstance(inv[r_idx], dict):
        inv[r_idx]["qty"] = r_qty - qty
        left = r_qty - qty
    else:
        inv.pop(r_idx)
        left = 0
    gained = 300 * qty
    await db.players.update_one(
        {"id": player_id},
        {"$set": {"inventory": inv}, "$inc": {"cash": gained}},
    )
    return {"message": f"Sold {qty} oz of Rock Candy for ${gained}", "cash_gained": gained, "oz_left": left}

'''


def main():
    if not SRV.exists():
        print("ROCK_CANDY_ITEM_ERROR: backend/server.py not found (run from /app)")
        return 1
    src = SRV.read_text(errors="ignore")
    orig = src
    landed = []

    # 1. Catalog entry.
    if "ROCK_CANDY_ITEM_CATALOG" in src:
        print("ROCK_CANDY_ITEM_CATALOG_ALREADY_APPLIED"); landed.append("catalog")
    else:
        anchor = "# Apply icon URLs to all equipment items"
        fallback = "ALL_ITEMS.update(LEVEL_ACCESSORIES)"
        if anchor in src:
            src = src.replace(anchor, CATALOG.strip() + "\n\n" + anchor, 1)
            print("ROCK_CANDY_ITEM_CATALOG_OK"); landed.append("catalog")
        elif fallback in src:
            src = src.replace(fallback, fallback + "\n" + CATALOG.strip(), 1)
            print("ROCK_CANDY_ITEM_CATALOG_OK"); landed.append("catalog")
        else:
            print("WARNING: catalog anchor not found - Rock Candy NOT added to ALL_ITEMS (item will be invisible on the item screen)")

    # 2. Exclude Rock Candy from the generic random drop pool (no double-drop).
    #    Tolerates a pool line already modified by Grass and/or Pills.
    if 'item["id"] != "rock_candy"' in src:
        print("ROCK_CANDY_ITEM_POOL_EXCLUDE_ALREADY_APPLIED"); landed.append("pool")
    else:
        pool_re = re.compile(r'if ((?:item\["id"\] != "[a-z_]+" and )*item\["level_requirement"\] <= enemy\["level"\] \+ 2)')
        m = pool_re.search(src)
        if m:
            src = src[:m.start(1)] + 'item["id"] != "rock_candy" and ' + src[m.start(1):]
            print("ROCK_CANDY_ITEM_POOL_EXCLUDE_OK"); landed.append("pool")
        else:
            print("WARNING: generic drop-pool anchor not found - Rock Candy may ALSO drop from the generic pool, so it could double-drop")

    # 3. Dedicated 1-in-10-per-fight drop on monster-battle victory.
    if "ROCK_CANDY_ITEM_DROP" in src:
        print("ROCK_CANDY_ITEM_DROP_ALREADY_APPLIED"); landed.append("drop")
    else:
        loot_at = src.find('combat_log.append(f"Loot drop: {dropped_item[\'name\']}!")')
        if loot_at == -1:
            print("WARNING: victory loot anchor not found - Rock Candy drop NOT added (no defeat hook)")
        else:
            upd_at = src.find("# Update player stats", loot_at)
            if upd_at == -1:
                print("WARNING: victory update anchor not found - Rock Candy drop NOT added (no defeat hook)")
            else:
                drop = ('            # ROCK_CANDY_ITEM_DROP: READING - 1-in-10 chance EACH fight (flat 10% roll), 1 oz, any monster enemy.\n'
                        '            if random.random() < (1/10):\n'
                        '                _rc_inv = player.get("inventory", [])\n'
                        '                _rc_idx = next((i for i, _it in enumerate(_rc_inv) if isinstance(_it, dict) and _it.get("item_id") == "rock_candy"), None)\n'
                        '                if _rc_idx is None:\n'
                        '                    _rc_inv.append({"item_id": "rock_candy", "qty": 1, "unit": "oz", "durability": 100, "max_durability": 100})\n'
                        '                else:\n'
                        '                    _rc_inv[_rc_idx]["qty"] = _rc_inv[_rc_idx].get("qty", 1) + 1\n'
                        '                await db.players.update_one({"id": player["id"]}, {"$set": {"inventory": _rc_inv}})\n'
                        '                rewards["items"] = (rewards.get("items") or []) + ["rock_candy"]\n'
                        '                combat_log.append("Loot drop: Rock Candy (1 oz)!")\n'
                        )
                src = src[:upd_at] + drop + src[upd_at:]
                print("ROCK_CANDY_ITEM_DROP_OK"); landed.append("drop")

    # 4. Inventory-details qty/unit passthrough (shared with Grass/Pills;
    #    whichever patch runs first adds it, the rest skip).
    if "ROCK_CANDY_ITEM_QTY" in src or "PILLS_ITEM_QTY" in src or "GRASS_ITEM_QTY" in src:
        print("ROCK_CANDY_ITEM_QTY_ALREADY_APPLIED"); landed.append("qty")
    else:
        anchor = 'item_with_durability["inventory_index"] = idx'
        if anchor in src:
            add = ('\n            # ROCK_CANDY_ITEM_QTY / PILLS_ITEM_QTY / GRASS_ITEM_QTY: pass stacked quantities through to the item screen.\n'
                   '            if inv_item.get("qty") is not None:\n'
                   '                item_with_durability["qty"] = inv_item["qty"]\n'
                   '            if inv_item.get("unit"):\n'
                   '                item_with_durability["unit"] = inv_item["unit"]')
            src = src.replace(anchor, anchor + add, 1)
            print("ROCK_CANDY_ITEM_QTY_OK"); landed.append("qty")
        else:
            print("WARNING: inventory-details anchor not found - oz count will NOT reach the item screen (Rock Candy will show without a quantity)")

    # 5. Attack hook: live multiplier at the two damage sites in battle_action.
    #    (No start_battle sum is touched: this hook checks expiry itself, so
    #    the Grass/Pills expiry part is irrelevant to Rock Candy.)
    if "ROCK_CANDY_ITEM_ATTACK" in src:
        print("ROCK_CANDY_ITEM_ATTACK_ALREADY_APPLIED"); landed.append("attack")
    else:
        stats_anchor = "player_stats = await get_effective_stats(player)"
        if stats_anchor not in src:
            print("WARNING: battle stats anchor not found - ATTACK HOOK NOT VERIFIED, need a live snippet of battle_action where player_stats is computed")
        else:
            flag = ('\n    # ROCK_CANDY_ITEM_ATTACK: a live Rock Candy buff multiplies damage by (1 + percent) for 60s.\n'
                    '    # Expiry-checked here; buffs without expires_at count. player_stats itself is NOT mutated\n'
                    '    # (it also feeds level-up growth, which must stay unboosted).\n'
                    '    _rc_now_iso = datetime.utcnow().isoformat()\n'
                    '    _rc_atk_mult = 1.0\n'
                    '    for _rc_b in player.get("active_buffs", []):\n'
                    '        if _rc_b.get("type") == "attack" and _rc_b.get("item_id") == "rock_candy":\n'
                    '            _rc_exp = _rc_b.get("expires_at")\n'
                    '            if (not _rc_exp) or (str(_rc_exp) >= _rc_now_iso):\n'
                    '                _rc_atk_mult = max(_rc_atk_mult, 1 + float(_rc_b.get("percent", 0.5)))')
            src = src.replace(stats_anchor, stats_anchor + flag, 1)
            ok = True
            normal_old = 'damage = max(1, player_stats["attack"] - enemy_stats.get("defense", 0) // 2)'
            if normal_old in src:
                src = src.replace(normal_old,
                    normal_old + '\n                if _rc_atk_mult > 1.0:\n                    damage = int(damage * _rc_atk_mult)', 1)
            else:
                print("WARNING: normal-attack damage anchor not found - normal attacks will NOT get the Rock Candy bonus")
                ok = False
            skill_old = 'damage = int(player_stats["attack"] * skill["damage_mult"])'
            if skill_old in src:
                src = src.replace(skill_old,
                    skill_old + '\n                if _rc_atk_mult > 1.0:\n                    damage = int(damage * _rc_atk_mult)', 1)
            else:
                print("WARNING: skill damage anchor not found - skills will NOT get the Rock Candy bonus")
                ok = False
            if ok:
                print("ROCK_CANDY_ITEM_ATTACK_OK"); landed.append("attack")
            else:
                print("ROCK_CANDY_ITEM_ATTACK_PARTIAL: multiplier flag added but a damage site was missed")

    # 6. Use + sell endpoints.
    if "ROCK_CANDY_ITEM_USE" in src and "ROCK_CANDY_ITEM_SELL" in src:
        print("ROCK_CANDY_ITEM_ENDPOINTS_ALREADY_APPLIED"); landed.append("endpoints")
    else:
        inc = "app.include_router(api_router)"
        if inc in src and "datetime" in src and "timedelta" in src and "uuid" in src:
            src = src.replace(inc, ROUTES.strip() + "\n\n\n" + inc, 1)
            print("ROCK_CANDY_ITEM_ENDPOINTS_OK"); landed.append("endpoints")
        else:
            print("WARNING: router anchor or datetime/timedelta/uuid imports not found - Rock Candy use/sell endpoints NOT added")

    if src == orig:
        print("ROCK_CANDY_ITEM_ALREADY_APPLIED")
        return 0
    try:
        compile(src, "server.py", "exec")
    except SyntaxError as e:
        print("ROCK_CANDY_ITEM_SYNTAX_FAIL: %s (file NOT written)" % e)
        return 1
    SRV.write_text(src)
    if len(landed) == 6:
        print("ROCK_CANDY_ITEM_OK")
    else:
        print("ROCK_CANDY_ITEM_PARTIAL: " + ",".join(landed))
    return 0

if __name__ == "__main__":
    sys.exit(main())
